create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,plan text not null default 'free' check(plan in('free','paid','professional')),generation_limit integer not null default 3,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ambassadors(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,display_name text not null,profession text,city text,state text,birth_place text,story text,highlights jsonb not null default '[]'::jsonb,quote text,gender text,created_at timestamptz not null default now());
create table if not exists public.generated_cards(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,full_name text,display_name text not null,profession text,city text,state text,birth_place text,story text,highlights jsonb not null default '[]'::jsonb,quote text,visual_location text,style text,gender text,original_photo_path text,generated_image_url text,prompt_used text,status text not null default 'pending',created_at timestamptz not null default now());
create table if not exists public.generation_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,generated_card_id uuid references public.generated_cards(id) on delete cascade,status text not null,model text,created_at timestamptz not null default now());
create table if not exists public.templates(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,style_config jsonb not null default '{}'::jsonb,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,active boolean not null default true,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.ambassadors enable row level security;alter table public.generated_cards enable row level security;alter table public.generation_history enable row level security;alter table public.templates enable row level security;alter table public.projects enable row level security;
create policy "profiles own rows" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "ambassadors own rows" on public.ambassadors for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "generated cards own rows" on public.generated_cards for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "generation history own rows" on public.generation_history for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "templates public read" on public.templates for select using(active=true);
create policy "projects public read" on public.projects for select using(active=true);
insert into public.templates(name,slug,description,style_config) values('Ane Cakes Fair','ane-cakes-fair','Card oficial de embaixadores','{"tone":"editorial","aspect":"4:5"}'),('Embaixador Premium','embaixador-premium','Versão premium','{"tone":"luxury","aspect":"4:5"}'),('História Inspiradora','historia-inspiradora','Foco narrativo','{"tone":"human","aspect":"4:5"}'),('Profissional em Destaque','profissional-destaque','Foco profissional','{"tone":"institutional","aspect":"4:5"}') on conflict(slug) do nothing;